/// Names the local Smooth terminal-handle action exposed only in the Curve Motif editor.
const MOTIF_SMOOTH_DIRECTION_LABEL: &str = "Smooth direction";
/// Describes Smooth's local next-edit effect without inventing persisted geometry metadata.
const MOTIF_SMOOTH_DIRECTION_DESCRIPTION: &str = "Keep the left and right end handles pointing in the same direction during later edits. Choosing this does not reshape the curve by itself.";
/// Names the local Corner terminal-handle action exposed only in the Curve Motif editor.
const MOTIF_CORNER_DIRECTION_LABEL: &str = "Corner";
/// Describes Corner's local next-edit effect without inventing persisted geometry metadata.
const MOTIF_CORNER_DIRECTION_DESCRIPTION: &str = "Let the left and right end handles point in different directions during later edits. Choosing this does not reshape the curve by itself.";

/// Defines the GTK-only modal width at which the construction layout stacks vertically.
const NARROW_EDITOR_MAX_WIDTH_PX: i32 = 700;

/// Defines the readable wide-layout sidebar request without fixing its vertical allocation.
const CONSTRUCTION_SIDEBAR_WIDTH_PX: i32 = 320;

/// Defines the smallest usable channel-settings sidebar allocation.
const MAIN_SIDEBAR_MIN_WIDTH_PX: i32 = 300;
/// Records the fixed intrinsic dimensions of the bundled neutral Wizard source.
const WIZARD_NEUTRAL_SOURCE_EDGE_PX: u32 = 100;
/// Bounds graph-backed topology on a large disposable canvas while preserving workspace aspect.
const WIZARD_PREVIEW_CANVAS_LONGEST_EDGE: f64 = 1024.0;
/// Fixes the private Wizard output target without changing export dimensions.
const WIZARD_PREVIEW_TARGET_PX: u32 = 256;
/// Sets the neutral preview's repeated-geometry baseline for Pattern size 1.0.
const WIZARD_PREVIEW_BASE_DENSITY: f64 = 8.0;
/// Caps neutral-preview density so expensive structural recipes remain responsive.
const WIZARD_PREVIEW_MAX_DENSITY: f64 = 12.0;
/// Retains enough neutral-preview geometry to make very coarse patterns legible.
const WIZARD_PREVIEW_MIN_DENSITY: f64 = 2.0;
/// Sets the lower structural baseline used when a preview must derive a connection graph.
const WIZARD_CONNECTION_PREVIEW_BASE_DENSITY: f64 = 32.0;
/// Caps graph-backed previews before guard expansion and adjacency construction amplify work.
const WIZARD_CONNECTION_PREVIEW_MAX_DENSITY: f64 = 40.0;
/// Keeps coarse graph-backed patterns visible at large Pattern size values.
const WIZARD_CONNECTION_PREVIEW_MIN_DENSITY: f64 = 16.0;
/// Changes the Wizard semantic grouping from side-by-side to stacked below this allocation.
const WIZARD_NARROW_MAX_WIDTH_PX: i32 = 760;
/// Fixes a readable non-expanding Presets card width for the responsive FlowBox grid.
const WIZARD_PRESET_CARD_WIDTH_PX: i32 = 220;

/// Defines the largest channel-settings sidebar allocation at wide window sizes.
const MAIN_SIDEBAR_MAX_WIDTH_PX: i32 = 420;

/// Reports whether a current editor allocation must use the reachable narrow layout.
const fn uses_narrow_editor_layout(width: i32) -> bool {
    width <= NARROW_EDITOR_MAX_WIDTH_PX
}

/// Computes the readable channel-settings width without letting it consume a wide preview.
const fn main_sidebar_width_for_window(width: i32) -> i32 {
    let requested = width / 3;
    if requested < MAIN_SIDEBAR_MIN_WIDTH_PX {
        MAIN_SIDEBAR_MIN_WIDTH_PX
    } else if requested > MAIN_SIDEBAR_MAX_WIDTH_PX {
        MAIN_SIDEBAR_MAX_WIDTH_PX
    } else {
        requested
    }
}

/// Computes the GtkPaned start position that leaves the active sidebar at its target width.
const fn main_split_position_for_window(width: i32) -> i32 {
    let position = width - main_sidebar_width_for_window(width);
    if position < 0 { 0 } else { position }
}

/// Applies the active-settings split policy without changing window, document, or preview state.
///
/// A hidden sidebar leaves the existing paned position alone. An active visible sidebar receives a
/// width derived from its current allocation, keeping selectors and descriptors usable at the app's
/// narrow minimum and avoiding oversized inspector allocation on wide displays.
fn apply_main_sidebar_width_policy(
    width: i32,
    drawer: &gtk::ToggleButton,
    inspector: &gtk::ScrolledWindow,
    split: &gtk::Paned,
) {
    if width > 0 && drawer.is_active() && inspector.is_visible() {
        split.set_position(main_split_position_for_window(width));
    }
}

/// Applies the current GTK-only construction reflow without touching draft or document state.
///
/// The sidebar and canvas stay in the static Blueprint hierarchy. This function changes only
/// their presentation allocation policy, preserving natural compact-control heights while the
/// vertically scrollable editor keeps every control reachable at narrow modal widths.
fn apply_pattern_editor_width_policy(
    width: i32,
    layout: &gtk::Box,
    sidebar: &gtk::Box,
    canvas: &gtk::DrawingArea,
) {
    if uses_narrow_editor_layout(width) {
        layout.set_orientation(gtk::Orientation::Vertical);
        sidebar.set_size_request(-1, -1);
        sidebar.set_hexpand(true);
        canvas.set_content_height(260);
    } else {
        layout.set_orientation(gtk::Orientation::Horizontal);
        sidebar.set_size_request(CONSTRUCTION_SIDEBAR_WIDTH_PX, -1);
        sidebar.set_hexpand(false);
        canvas.set_content_height(220);
    }
}

/// Retains one private-editor descriptor row and its immutable source value.
///
/// Rows are keyed by descriptor identity so accepted draft edits preserve
/// unaffected widget/focus instances. The row never owns document, scheduler,
/// or savepoint authority.
struct DraftDescriptorComponent {
    row: gtk::Box,
    control: gtk::Widget,
    value: PropertyCurrentValue,
}

/// Owns an intentionally private structural-editing session for one channel.
///
/// Its history starts from a cloned main document and never escapes into the
/// main workspace, savepoint, source bundle, scheduler, or filesystem.
struct PatternEditorDraft {
    history: DocumentHistory,
    selected_channel: ChannelId,
    initial_document: Document,
    discard_confirmed: bool,
    sources: SourceBundle,
    presentation: SourcePresentation,
    scheduler: Arc<EvaluationScheduler>,
    preview_submission: Option<u64>,
    epoch: u64,
    geometry_editor: stage20f_editor::Stage20fEditorState,
    construction_attachment: Option<AuthoredStructureAttachment>,
    pending_shared_edit: Option<PendingSharedPathEdit>,
    invoking_use: Option<AuthoredStructureUse>,
}

/// Retains a gated private replacement until the artist chooses its shared-resource policy.
///
/// The value stays within the private Pattern Editor and contains no main workspace or preview
/// authority. It is consumed only by an explicit Edit all uses or Make a copy for this use choice.
#[derive(Clone)]
struct PendingSharedPathEdit {
    selected_use: toniator_domain::AuthoredStructureUse,
    base_structure: toniator_domain::AuthoredStructure,
    replacement: toniator_domain::AuthoredStructureDraft,
}

/// Retains one persistent sidebar row and its last immutable descriptor value.
