/// Rebuilds the visible All and real-channel segmented selector from document topology.
///
/// Each segment uses the authoritative modeled role for its text and accent.
/// The GTK group is runtime-only and never fabricates a channel identifier.
fn rebuild_channel_segments(
    state: &Rc<RefCell<AppState>>,
    document: Option<&Document>,
    channel_ids: &[ChannelId],
    selected: InspectorTarget,
) {
    let container = state.borrow().channel_segments.clone();
    while let Some(child) = container.first_child() {
        container.remove(&child);
    }
    let Some(document) = document else {
        container.set_sensitive(false);
        return;
    };
    container.set_sensitive(true);
    let all = gtk::ToggleButton::with_label("All");
    all.set_active(selected == InspectorTarget::DocumentAll);
    all.set_tooltip_text(Some(
        "Edit the document base while preserving channel overrides",
    ));
    all.update_property(&[
        gtk::accessible::Property::Label("All channels"),
        gtk::accessible::Property::Description(
            "Edit the document base while preserving channel overrides.",
        ),
    ]);
    connect_channel_segment(state, &all, InspectorTarget::DocumentAll);
    container.append(&all);
    for channel_id in channel_ids {
        let button = gtk::ToggleButton::with_label(&channel_segment_label(document, *channel_id));
        button.set_group(Some(&all));
        button.set_active(selected == InspectorTarget::Channel(*channel_id));
        let name = channel_display_name(document, *channel_id);
        let description = format!("Edit the {name} channel without isolating the preview.");
        button.set_tooltip_text(Some(&description));
        button.update_property(&[
            gtk::accessible::Property::Label(&name),
            gtk::accessible::Property::Description(&description),
        ]);
        if let Some(class) = channel_segment_css_class(document, *channel_id) {
            button.add_css_class(class);
        }
        connect_channel_segment(state, &button, InspectorTarget::Channel(*channel_id));
        container.append(&button);
    }
}

/// Connects one real GTK segment to runtime inspector selection only.
fn connect_channel_segment(
    state: &Rc<RefCell<AppState>>,
    button: &gtk::ToggleButton,
    target: InspectorTarget,
) {
    let state = Rc::clone(state);
    button.connect_toggled(move |button| {
        if !button.is_active() || state.borrow().syncing_inspector {
            return;
        }
        {
            let mut app_state = state.borrow_mut();
            let previous_target = app_state.inspector_runtime.target;
            app_state.inspector_runtime.target = target;
            app_state.inspector_runtime.focus = None;
            if previous_target != target {
                clear_structural_edit_context_for_selection(&mut app_state.inspector_runtime);
            }
        }
        if let InspectorTarget::Channel(channel_id) = target {
            dispatch_ui_intent(&state, UiIntent::SelectChannel(channel_id));
        } else {
            schedule_inspector_rebuild(&state);
        }
    });
}

/// Summarizes the three recipe facts shown persistently in the main inspector.
#[derive(Clone, Debug, PartialEq, Eq)]
struct MainRecipeSummary {
    family: String,
    sites: String,
    connections: String,
}

/// Resolves one target's current recipe, reporting mixed All-channel authority truthfully.
fn main_recipe_summary(document: &Document, target: InspectorTarget) -> Option<MainRecipeSummary> {
    let definition_id = match target {
        InspectorTarget::DocumentAll => document.pattern_settings().definition_id,
        InspectorTarget::Channel(channel_id) => document.pattern_definition_for(channel_id)?.id,
    };
    let recipe = document
        .reconstruct_pattern_definition_recipe(definition_id)
        .ok()?;
    if target == InspectorTarget::DocumentAll {
        let mixed = authoritative_channel_ids(document)
            .into_iter()
            .any(|channel_id| {
                document
                    .pattern_definition_for(channel_id)
                    .and_then(|definition| {
                        document
                            .reconstruct_pattern_definition_recipe(definition.id)
                            .ok()
                    })
                    .is_some_and(|channel_recipe| channel_recipe != recipe)
            });
        if mixed {
            return Some(MainRecipeSummary {
                family: "Mixed".to_owned(),
                sites: "Varies by channel".to_owned(),
                connections: "Varies by channel".to_owned(),
            });
        }
    }
    Some(MainRecipeSummary {
        family: wizard_family_label(recipe.family_kind()).to_owned(),
        sites: wizard_site_generation_label(recipe.site_generation_kind()).to_owned(),
        connections: main_recipe_connection_summary(&recipe),
    })
}

/// Returns a concise connection summary from the reconstructed recipe only.
fn main_recipe_connection_summary(recipe: &PatternDefinitionRecipe) -> String {
    let structure = &recipe.structure;
    if recipe_structure_contains_curve_motif(structure) {
        return "Motif paths".to_owned();
    }
    if recipe_structure_contains_maze(structure) {
        return "Maze".to_owned();
    }
    let Ok(kinds) = recipe.construction_kinds() else {
        return "Unavailable".to_owned();
    };
    let methods = kinds
        .into_iter()
        .enumerate()
        .filter_map(|(index, kind)| {
            (kind == PatternRecipeConstructionKind::Connections)
                .then(|| recipe.connection_method_kind(index).ok().flatten())
                .flatten()
                .map(wizard_connection_method_label)
        })
        .collect::<BTreeSet<_>>();
    if methods.is_empty() {
        "None".to_owned()
    } else {
        methods.into_iter().collect::<Vec<_>>().join(", ")
    }
}

/// Reports whether a nested recipe structure contains authored motif paths.
fn recipe_structure_contains_curve_motif(structure: &PatternStructureRecipe) -> bool {
    match structure {
        PatternStructureRecipe::CurveMotifPaths { .. } => true,
        PatternStructureRecipe::AuthoredResources { definition, .. }
        | PatternStructureRecipe::ConnectionPaths { definition, .. }
        | PatternStructureRecipe::MazeWalls { definition, .. }
        | PatternStructureRecipe::AuthoredClosedShapeMarks { definition, .. }
        | PatternStructureRecipe::VoronoiRegions { definition }
        | PatternStructureRecipe::GuideFaceRegions { definition, .. } => {
            recipe_structure_contains_curve_motif(definition)
        }
        PatternStructureRecipe::OrderedOutputs { definition, .. } => {
            recipe_structure_contains_curve_motif(definition)
        }
        _ => false,
    }
}

/// Reports whether a nested recipe structure contains maze-wall output.
fn recipe_structure_contains_maze(structure: &PatternStructureRecipe) -> bool {
    match structure {
        PatternStructureRecipe::MazeWalls { .. } => true,
        PatternStructureRecipe::AuthoredResources { definition, .. }
        | PatternStructureRecipe::ConnectionPaths { definition, .. }
        | PatternStructureRecipe::AuthoredClosedShapeMarks { definition, .. }
        | PatternStructureRecipe::CurveMotifPaths { definition, .. }
        | PatternStructureRecipe::VoronoiRegions { definition }
        | PatternStructureRecipe::GuideFaceRegions { definition, .. } => {
            recipe_structure_contains_maze(definition)
        }
        PatternStructureRecipe::OrderedOutputs { definition, .. } => {
            recipe_structure_contains_maze(definition)
        }
        _ => false,
    }
}

/// Projects an optional recipe summary into the three visible and accessible values.
fn project_main_recipe_summary(state: &Rc<RefCell<AppState>>, summary: Option<&MainRecipeSummary>) {
    let app_state = state.borrow();
    for (label, name, value) in [
        (
            &app_state.recipe_family,
            "Pattern family",
            summary.map(|value| value.family.as_str()),
        ),
        (
            &app_state.recipe_sites,
            "Pattern sites",
            summary.map(|value| value.sites.as_str()),
        ),
        (
            &app_state.recipe_connections,
            "Pattern connections",
            summary.map(|value| value.connections.as_str()),
        ),
    ] {
        let value = value.unwrap_or("—");
        label.set_label(value);
        label.update_property(&[
            gtk::accessible::Property::Label(name),
            gtk::accessible::Property::Description(&format!("{name}: {value}")),
        ]);
    }
}

fn inspector_key(descriptor: &PropertyDescriptor) -> String {
    format!("{:?}:{:?}", descriptor.target, descriptor.field)
}

#[cfg(test)]
fn focus_for_descriptor(
    descriptor: &PropertyDescriptor,
    collection_index: Option<usize>,
) -> InspectorFocusIdentity {
    InspectorFocusIdentity::Descriptor {
        key: inspector_key(descriptor),
        field: descriptor.field,
        collection_index,
        guide_ordinal: None,
    }
}

fn focus_for_descriptor_in_values(
    values: &[PropertyCurrentValue],
    descriptor: &PropertyDescriptor,
    collection_index: Option<usize>,
) -> InspectorFocusIdentity {
    let guide_ordinal = match descriptor.target {
        PropertyTarget::GuideDimension(..) => values
            .iter()
            .filter(|value| {
                value.descriptor.field == descriptor.field
                    && matches!(value.descriptor.target, PropertyTarget::GuideDimension(..))
            })
            .position(|value| value.descriptor.target == descriptor.target),
        _ => None,
    };
    InspectorFocusIdentity::Descriptor {
        key: inspector_key(descriptor),
        field: descriptor.field,
        collection_index,
        guide_ordinal,
    }
}

fn focus_with_collection_index(
    focus: &InspectorFocusIdentity,
    collection_index: usize,
) -> InspectorFocusIdentity {
    match focus {
        InspectorFocusIdentity::Descriptor {
            key,
            field,
            guide_ordinal,
            ..
        } => InspectorFocusIdentity::Descriptor {
            key: key.clone(),
            field: *field,
            collection_index: Some(collection_index),
            guide_ordinal: *guide_ordinal,
        },
    }
}

/// Selects document and active-definition descriptor values for one channel.
///
/// Effective definition identity comes only from the domain resolver; this
/// presentation filter never reconstructs inheritance or persisted deltas.
fn selected_property_values(
    document: &Document,
    channel_id: ChannelId,
) -> Vec<PropertyCurrentValue> {
    document
        .property_values()
        .into_iter()
        .filter(|value| match value.descriptor.target {
            PropertyTarget::Document => true,
            PropertyTarget::Channel(id) => id == channel_id,
            PropertyTarget::ChannelOutput(id, _) => id == channel_id,
            PropertyTarget::Definition(id)
            | PropertyTarget::Mechanism(id, _)
            | PropertyTarget::OutputLayer(id, _)
            | PropertyTarget::GuideDimension(id, _, _) => document
                .effective_channel_pattern(channel_id)
                .map(|pattern| pattern.definition_id == id)
                .unwrap_or(false),
        })
        .collect()
}

/// Projects the capability-valid frequent controls for the current inspector target.
///
/// Structural topology, source mapping, paint/color, and output-response controls
/// are intentionally omitted from the main window. Those belong to Advanced
/// Settings or the Stage 21B Pattern Wizard. Every returned value retains its
/// authoritative descriptor and can therefore build a valid domain command.
fn inline_inspector_values(
    document: &Document,
    target: InspectorTarget,
) -> Vec<PropertyCurrentValue> {
    let scope = match target {
        InspectorTarget::DocumentAll => PatternCapabilityScope::DocumentBase,
        InspectorTarget::Channel(channel_id) => PatternCapabilityScope::Channel(channel_id),
    };
    let active = document
        .pattern_capabilities(scope)
        .map(|projection| projection.active_controls)
        .unwrap_or_default();
    let is_active = |descriptor: &PropertyDescriptor| active.contains(descriptor);
    let effective_definition_id = match target {
        InspectorTarget::DocumentAll => Some(document.pattern_settings().definition_id),
        InspectorTarget::Channel(channel_id) => document
            .pattern_definition_for(channel_id)
            .map(|definition| definition.id),
    };
    let is_active_seed = |descriptor: &PropertyDescriptor| {
        matches!(
            descriptor.field,
            PropertyFieldId::RandomSeed
                | PropertyFieldId::ConnectionSeed
                | PropertyFieldId::MazeSeed
        ) && target_definition_id(descriptor.target) == effective_definition_id
            && is_active(descriptor)
    };
    document
        .property_values()
        .into_iter()
        .filter(|value| match target {
            InspectorTarget::DocumentAll => {
                (value.descriptor.target == PropertyTarget::Document
                    && is_active(&value.descriptor)
                    && matches!(
                        value.descriptor.field,
                        PropertyFieldId::Density
                            | PropertyFieldId::DensityAspect
                            | PropertyFieldId::RotationDegrees
                            | PropertyFieldId::ShapeRotationDegrees
                    ))
                    || is_active_seed(&value.descriptor)
            }
            InspectorTarget::Channel(channel_id) => {
                (value.descriptor.target == PropertyTarget::Channel(channel_id)
                    && matches!(
                        value.descriptor.field,
                        PropertyFieldId::Density
                            | PropertyFieldId::DensityAspect
                            | PropertyFieldId::RotationDegrees
                            | PropertyFieldId::TranslationX
                            | PropertyFieldId::TranslationY
                            | PropertyFieldId::ShapeRotationDegrees
                            | PropertyFieldId::Opacity
                            | PropertyFieldId::Visibility
                    )
                    && (is_active(&value.descriptor)
                        || matches!(
                            value.descriptor.field,
                            PropertyFieldId::TranslationX
                                | PropertyFieldId::TranslationY
                                | PropertyFieldId::Opacity
                                | PropertyFieldId::Visibility
                        )))
                    || is_active_seed(&value.descriptor)
            }
        })
        .collect()
}

/// Returns the effective artist-facing pattern name for a document or channel target.
fn target_pattern_name(document: &Document, target: InspectorTarget) -> String {
    match target {
        InspectorTarget::DocumentAll => document
            .property_values()
            .into_iter()
            .find(|value| {
                value.descriptor.target == PropertyTarget::Document
                    && value.descriptor.field == PropertyFieldId::DefinitionSelection
            })
            .and_then(|value| match value.value {
                PropertyCurrentValueKind::Reference(PropertyReferenceValue::Definition(
                    definition_id,
                )) => document
                    .pattern_definition_bundles()
                    .iter()
                    .find(|bundle| bundle.definition.id == definition_id)
                    .map(|bundle| bundle.definition.name.clone()),
                _ => None,
            })
            .unwrap_or_else(|| "Custom pattern".to_owned()),
        InspectorTarget::Channel(channel_id) => {
            artist_pattern_name(&selected_property_values(document, channel_id))
        }
    }
}

/// Classifies descriptor targets that edit a document-owned pattern definition.
///
/// Channel and document targets remain in the channel inspector; every other
/// supported target belongs to the transient Pattern Editor. This classification
/// is presentation-only and never changes descriptor, command, or history
/// authority.
#[allow(dead_code)] // Retained for the Stage 21B nested Pattern Wizard integration.
fn is_structural_descriptor(descriptor: &PropertyDescriptor) -> bool {
    !matches!(
        descriptor.target,
        PropertyTarget::Document | PropertyTarget::Channel(_)
    )
}

/// Returns only selected-channel instance and presentation values for the
/// sidebar inspector. Structural values are deliberately excluded so the
/// sidebar cannot become an alternate Pattern Editor. Stage 20G also keeps
/// undisclosed document-base inheritance controls out of this existing
/// channel workflow; source selection and authoritative density values are
/// retained because they are established controls at those locations.
#[allow(dead_code)] // Retained for the Stage 21B nested Pattern Wizard integration.
fn channel_inspector_values(values: &[PropertyCurrentValue]) -> Vec<PropertyCurrentValue> {
    values
        .iter()
        .filter(|value| {
            !is_structural_descriptor(&value.descriptor)
                && match value.descriptor.target {
                    PropertyTarget::Document => matches!(
                        value.descriptor.field,
                        PropertyFieldId::SourceReference
                            | PropertyFieldId::Density
                            | PropertyFieldId::DensityAspect
                    ),
                    _ => true,
                }
        })
        .cloned()
        .collect()
}

/// Returns only the selected purpose's descriptor values for one private editor.
///
/// The immutable reader remains the source of current values. This filter neither materializes a
/// definition copy nor exposes a Grid field in Mark Editor (or vice versa).
fn pattern_editor_values(
    values: &[PropertyCurrentValue],
    purpose: PatternEditorPurpose,
) -> Vec<PropertyCurrentValue> {
    values
        .iter()
        .filter(|value| descriptor_belongs_to_editor(&value.descriptor.field, purpose))
        .cloned()
        .collect()
}

/// Reports whether one structural descriptor belongs to the specified purpose-specific editor.
///
/// The filter is presentation policy only: descriptors and their typed commands remain owned by
/// the domain, and fields omitted here cannot be mutated through this GTK modal.
fn descriptor_belongs_to_editor(field: &PropertyFieldId, purpose: PatternEditorPurpose) -> bool {
    matches!(
        (purpose, field),
        (
            PatternEditorPurpose::Grid,
            PropertyFieldId::Density
                | PropertyFieldId::DensityAspect
                | PropertyFieldId::RotationDegrees
                | PropertyFieldId::TranslationX
                | PropertyFieldId::TranslationY
                | PropertyFieldId::GuideBaselineAngle
                | PropertyFieldId::GuidePhase
                | PropertyFieldId::GuideSpacingMultiplier
                | PropertyFieldId::GuidePrototype
                | PropertyFieldId::GuideAuthoredStructure
                | PropertyFieldId::GuideArcCenterX
                | PropertyFieldId::GuideArcCenterY
                | PropertyFieldId::GuideArcRadius
                | PropertyFieldId::GuideArcStartAngle
                | PropertyFieldId::GuideArcSweepAngle
                | PropertyFieldId::GuideRepetition
                | PropertyFieldId::GuideOffsetSpacing
                | PropertyFieldId::GuideOffsetCleanup
                | PropertyFieldId::GuideStackDirection
                | PropertyFieldId::GuideStackSpacingMultiplier
                | PropertyFieldId::IntersectionDimensions
                | PropertyFieldId::IntersectionMergeEpsilon
                | PropertyFieldId::AlongGuideDimensions
                | PropertyFieldId::AlongGuideIntervalMultiplier
                | PropertyFieldId::AlongGuidePhase
                | PropertyFieldId::CoverageGuardSteps
                | PropertyFieldId::CoverageAdditionalMargin
        ) | (
            PatternEditorPurpose::Mark,
            PropertyFieldId::MarkMinimumFill
                | PropertyFieldId::MarkMaximumFill
                | PropertyFieldId::ShapeRotationDegrees
                | PropertyFieldId::OutputSiteProduct
                | PropertyFieldId::OutputPrototype
                | PropertyFieldId::OutputAuthoredClosedShape
                | PropertyFieldId::OutputOrientation
                | PropertyFieldId::OutputOrientationDimension
        )
    )
}

/// Resolves the retained descriptor focus through one real selected-channel projection.
///
/// A missing or removed channel produces no values and therefore cannot retain
/// a stale focus identity or fabricate a replacement channel.
#[allow(dead_code)] // Retained as the tested focus policy for the Stage 21B editor integration.
fn resolve_focus_after_document_change(
    document: &Document,
    selected_channel: Option<ChannelId>,
    focus: Option<InspectorFocusIdentity>,
) -> Option<InspectorFocusIdentity> {
    let values = selected_channel
        .map(|channel_id| selected_property_values(document, channel_id))
        .unwrap_or_default();
    resolve_descriptor_focus(&values, focus)
}

fn resolve_descriptor_focus(
    values: &[PropertyCurrentValue],
    focus: Option<InspectorFocusIdentity>,
) -> Option<InspectorFocusIdentity> {
    let Some(InspectorFocusIdentity::Descriptor {
        key,
        field,
        collection_index,
        guide_ordinal,
    }) = focus
    else {
        return focus;
    };
    if values
        .iter()
        .any(|value| inspector_key(&value.descriptor) == key)
    {
        return Some(InspectorFocusIdentity::Descriptor {
            key,
            field,
            collection_index,
            guide_ordinal,
        });
    }
    let matching = values
        .iter()
        .filter(|value| value.descriptor.field == field)
        .collect::<Vec<_>>();
    let replacement = if let Some(guide_ordinal) = guide_ordinal {
        matching
            .into_iter()
            .filter(|value| matches!(value.descriptor.target, PropertyTarget::GuideDimension(..)))
            .nth(guide_ordinal)
    } else {
        matching.into_iter().next()
    }?;
    Some(focus_for_descriptor_in_values(
        values,
        &replacement.descriptor,
        collection_index,
    ))
}

/// Selects one of the visible v1.2 main-inspector groups for an inline descriptor.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
enum MainInspectorSection {
    Appearance,
    Variation,
    Options,
}

/// Classifies frequent controls without changing descriptor applicability or command authority.
fn main_inspector_section(field: PropertyFieldId) -> MainInspectorSection {
    match field {
        PropertyFieldId::Density
        | PropertyFieldId::DensityAspect
        | PropertyFieldId::RotationDegrees => MainInspectorSection::Appearance,
        PropertyFieldId::RandomSeed
        | PropertyFieldId::ConnectionSeed
        | PropertyFieldId::MazeSeed => MainInspectorSection::Variation,
        _ => MainInspectorSection::Options,
    }
}

/// Returns the resource-owned container for one main-inspector section.
fn main_inspector_container(state: &AppState, section: MainInspectorSection) -> gtk::Box {
    match section {
        MainInspectorSection::Appearance => state.appearance_controls.clone(),
        MainInspectorSection::Variation => state.variation_controls.clone(),
        MainInspectorSection::Options => state.options_controls.clone(),
    }
}

