    /// Verifies compiled GTK templates retain their loadable and accessible static hierarchy.
    ///
    /// This check exercises the normal GResource boundary without creating a display, document,
    /// history, scheduler, or file side effect. A missing resource or an accidental Adwaita type
    /// makes the application fail before any window can be presented.
    #[test]
    fn gtk_blueprint_resources_register_and_remain_adwaita_free() {
        register_resources();
        for resource in [
            "window.ui",
            "channel-editor.ui",
            "pattern-editor.ui",
            "advanced-settings.ui",
            "pattern-wizard.ui",
            "pattern-wizard-card.ui",
            "preset-row.ui",
            "confirmation-dialog.ui",
            "png-export-options.ui",
        ] {
            let data = gio::resources_lookup_data(
                &format!("{RESOURCE_PREFIX}/{resource}"),
                gio::ResourceLookupFlags::NONE,
            )
            .expect("build-compiled Blueprint resource remains registered");
            let template = std::str::from_utf8(data.as_ref())
                .expect("Blueprint compiler emits UTF-8 GtkBuilder XML");
            assert!(
                template.contains("Gtk"),
                "{resource} remains a GTK template"
            );
            assert!(
                !template.contains("Adw"),
                "{resource} must not reintroduce an Adwaita type"
            );
            if resource == "window.ui" {
                assert!(
                    template.contains("GtkStackPage")
                        && template.contains("name=\"child\"")
                        && template.contains("type=\"start\"")
                        && template.contains("type=\"end\""),
                    "window must retain named stack-page widgets and valid paned child roles"
                );
                assert!(
                    template.contains("id=\"main_banner_dismiss\"")
                        && template.contains("id=\"preview_overall_progress_label\"")
                        && template.contains("id=\"preview_progress_bar\"")
                        && template.contains("id=\"preview_stage_progress_bar\"")
                        && template.contains("id=\"preview_progress_label\"")
                        && !template.contains("id=\"preview_spinner\""),
                    "main canvas exposes dismissible errors and staged determinate progress"
                );
            }
            if resource == "pattern-editor.ui" {
                assert!(
                    template.contains("id=\"construction_canvas_heading\"")
                        && template.contains("Curve preview"),
                    "the visible curve-preview heading remains a stable accessibility relation source"
                );
                assert!(
                    template.contains("GtkToggleButton")
                        && template.contains("smooth_direction")
                        && template.contains("corner_direction"),
                    "terminal direction remains a native GTK toggle group rather than CSS-only state"
                );
            }
        }
        for resource in WIZARD_IMAGE_RESOURCE_PATHS {
            let data = gio::resources_lookup_data(resource, gio::ResourceLookupFlags::NONE)
                .expect("Gate 21B-2 card image resource remains in the registered bundle");
            assert!(
                !data.is_empty(),
                "Gate 21B-2 card image resource must retain content: {resource}"
            );
        }
    }

